package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.Jsoup;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class Element_siblingElements_TriageGen1Test {

    @Test
    public void testSiblingElements_WithNoSiblings() {
        Document doc = Jsoup.parse("<div><p>Test</p></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingElements_WithOneSibling() {
        Document doc = Jsoup.parse("<div><p>Test1</p><p>Test2</p></div>");
        Element p1 = doc.select("p").first();
        Elements siblings = p1.siblingElements();
        assertEquals(1, siblings.size());
        assertEquals("Test2", siblings.first().text());
    }

    @Test
    public void testSiblingElements_WithMultipleSiblings() {
        Document doc = Jsoup.parse("<div><p>Test1</p><span>Test2</span><p>Test3</p></div>");
        Element p1 = doc.select("p").first();
        Elements siblings = p1.siblingElements();
        assertEquals(2, siblings.size());
        assertEquals("Test2", siblings.get(0).text());
        assertEquals("Test3", siblings.get(1).text());
    }

    @Test
    public void testSiblingElements_WithParentNoChildren() {
        Document doc = Jsoup.parse("<div></div>");
        Element div = doc.select("div").first();
        Elements siblings = div.siblingElements();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingElements_WithEmptyParentChildren() {
        Document doc = Jsoup.parse("<div><p></p></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingElements_WithTextAndElements() {
        Document doc = Jsoup.parse("<div><p>Text</p><span>Element</span></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertEquals(1, siblings.size());
        assertEquals("Element", siblings.first().text());
    }

    @Test
    public void testSiblingElements_WithNestedElements() {
        Document doc = Jsoup.parse("<div><p>Text</p><div><span>Element</span></div></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertEquals(1, siblings.size());
        assertEquals("Element", siblings.first().select("span").text());
    }

    @Test
    public void testSiblingElements_WithSelfAsSibling() {
        Document doc = Jsoup.parse("<div><p>Test</p></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertTrue(!siblings.contains(p));
    }

    @Test
    public void testSiblingElements_WithNestedParent() {
        Document doc = Jsoup.parse("<div><div><p>Test</p></div></div>");
        Element p = doc.select("p").first();
        Elements siblings = p.siblingElements();
        assertEquals(0, siblings.size());
    }

    @Test
    public void testSiblingElements_WithAttributes() {
        Document doc = Jsoup.parse("<div><p id='test'>Test</p><p>Another</p></div>");
        Element p1 = doc.select("p#test").first();
        Elements siblings = p1.siblingElements();
        assertEquals(1, siblings.size());
        assertEquals("Another", siblings.first().text());
    }

    @Test
    public void testSiblingElements_WithEmptyDocument() {
        Document doc = Jsoup.parse("");
        Element root = doc.body();
        Elements siblings = root.siblingElements();
        assertEquals(0, siblings.size());
    }
}
